  3  /**
  4   * Runtime API client for the Agent Playground.
  5   *
  6   * This module speaks the `/agent-runs/**` runtime contract only. The
  7   * observability product API (`lib/runs.ts`, `/runs/**`) is a different
  8   * contract with a different response shape and is never mixed in here.
  9   */
 10  
 11  function runtimeBase(workspaceId: string): string {
 12    return `/api/v1/workspaces/${encodeURIComponent(workspaceId)}`;
 13  }
 14  
 15  /**
 16   * Authoritative runtime Run as persisted by the backend. After any
 17   * terminal stream event the UI re-reads this record and trusts it over
 18   * whatever the stream accumulated.
 19   */
 20  export type AgentRun = {
 21    id: string;
 22    workspace_id: string;
 23    agent_version_id: string;
 24    status: string;
 25    /**
 26     * Null for a reader who only holds `workspace_read`: the backend withholds
 27     * the raw prompt and the model's answer from anyone without `agent_run`.
 28     * The fields stay present in the contract; only their content is gated.
 29     */
 30    input_text: string | null;
 31    final_output: string | null;
 32    failure_code: string | null;
 33    resolved_spec_hash: string | null;
 34    /** One entry per resolved knowledge snapshot, not a keyed object. */
 35    effective_knowledge_snapshots: Array<Record<string, unknown>>;
 36    model_step_count: number;
 37    tool_call_count: number;
 38    total_input_tokens: number | null;
 39    total_output_tokens: number | null;
 40    total_tokens: number | null;
 41    total_cached_tokens: number | null;
 42    /** Decimal on the wire: it may arrive as a number or a string. */
 43    total_cost_amount: number | string | null;
 44    cost_currency: string | null;
 45    cost_is_estimate: boolean | null;
 46    created_by: string;
 47    created_at: string;
 48    /** A persisted run has always started; only completion is optional. */
 49    started_at: string;
 50    completed_at: string | null;
 51  };
 52  
 53  export function getAgentRun(input: AuthInput, runId: string): Promise<AgentRun> {
 54    return apiRequest<AgentRun>(
 55      `${runtimeBase(input.workspaceId)}/agent-runs/${encodeURIComponent(runId)}`,
 56      input.accessToken,
 57    );
 58  }
