 92  /** Frozen runtime event vocabulary. No client-invented types are accepted. */
 93  export const AGENT_EVENT_TYPES = [
 94    "run.started",
 95    "message.started",
 96    "context.budget",
 97    "message.delta",
 98    "message.completed",
 99    "retrieval.started",
100    "retrieval.completed",
101    "rerank.completed",
102    "tool.requested",
103    "tool.started",
104    "tool.completed",
105    "tool.failed",
106    "approval.required",
107    "approval.resolved",
108    "run.cancel_requested",
109    "usage",
110    "run.completed",
111    "run.failed",
112    "run.cancelled",
113  ] as const;
114  
115  export type AgentEventType = (typeof AGENT_EVENT_TYPES)[number];
116  
117  export type AgentEvent = {
118    event_id: string;
119    type: AgentEventType;
120    request_id: string;
121    run_id: string;
122    step_id: string | null;
123    timestamp: string;
124    payload: Record<string, unknown>;
125    sequence: number;
126    agent_version_id: string;
127  };
