138  /**
139   * One decoded SSE frame. `comment` frames (`: heartbeat`) carry no data
140   * field and are never business events.
141   */
142  type SseFrame = { event: string | null; data: string | null };
143  
144  function decodeFrame(raw: string): SseFrame {
145    let event: string | null = null;
146    const dataLines: string[] = [];
147    for (const line of raw.split("\n")) {
148      // A leading colon marks a comment; heartbeats arrive exactly this way.
149      if (line === "" || line.startsWith(":")) continue;
150      const colon = line.indexOf(":");
151      const field = colon === -1 ? line : line.slice(0, colon);
152      let value = colon === -1 ? "" : line.slice(colon + 1);
153      if (value.startsWith(" ")) value = value.slice(1);
154      if (field === "event") event = value;
155      else if (field === "data") dataLines.push(value);
156    }
157    return { event, data: dataLines.length > 0 ? dataLines.join("\n") : null };
158  }
159  
160  /**
161   * Validates one frame against the frozen AgentEvent contract.
162   * Returns null for heartbeats and other dataless frames; throws a
163   * STREAM_PROTOCOL_ERROR for frames that claim to be events but are not.
164   */
165  export function parseAgentEventFrame(raw: string): AgentEvent | null {
166    const frame = decodeFrame(raw);
167    if (frame.data === null) return null;
168  
169    let parsed: unknown;
170    try {
171      parsed = JSON.parse(frame.data);
172    } catch {
173      throw streamProtocolError("A stream frame contained data that is not valid JSON.");
174    }
175    if (!isRecord(parsed)) {
176      throw streamProtocolError("A stream frame contained data that is not an object.");
177    }
178    if (typeof parsed.type !== "string") {
179      throw streamProtocolError("A stream event is missing its type.");
180    }
